package dk.jamesbabz.madkursus.inbound.rest.recipetemplate;
import java.time.ZoneOffset;import dk.jamesbabz.madkursus.inbound.rest.dto.*;import dk.jamesbabz.madkursus.inbound.rest.producttemplate.ProductTemplateRestMapper;import dk.jamesbabz.madkursus.service.applications.RecipeTemplateService;import dk.jamesbabz.madkursus.service.models.RecipeTemplate;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;
@Component @RequiredArgsConstructor public class RecipeTemplateRestMapper{private final ProductTemplateRestMapper products;private final RecipeTemplateService service;public RecipeTemplateSummaryDTO summary(RecipeTemplate t){var copied=service.copiedRecipe(t.id());return new RecipeTemplateSummaryDTO(t.id(),t.name(),t.active(),copied.isPresent()).description(t.description()).userRecipeId(copied.map(r->r.id()).orElse(null));}public RecipeTemplateDTO detail(RecipeTemplate t){var copied=service.copiedRecipe(t.id());return new RecipeTemplateDTO(t.id(),t.name(),t.active(),copied.isPresent(),t.createdAt().atOffset(ZoneOffset.UTC),t.updatedAt().atOffset(ZoneOffset.UTC),t.ingredients().stream().map(i->new RecipeTemplateIngredientDTO(i.id(),products.toDto(i.productTemplate()),i.quantity(),RecipeUnitDTO.valueOf(i.unit().name()),i.sortOrder()).preparation(i.preparation())).toList(),t.steps().stream().map(s->new RecipeTemplateStepDTO(s.id(),s.instruction(),s.sortOrder())).toList()).description(t.description()).userRecipeId(copied.map(r->r.id()).orElse(null));}}
